import numpy as np, time, statistics
from eigen import find_dominant_eigenvalue_and_eigenvector as F
bad=0
for n in range(1,11):
    for t in range(200):
        A=np.random.normal(size=(n,n))
        lam,vec=F(A)
        if not np.allclose(A@vec, lam*vec):
            bad+=1; print('FAIL',n,lam); break
print('bad',bad)
mis=0
for t in range(500):
    n=int(np.random.randint(2,11)); A=np.random.normal(size=(n,n))
    lam,vec=F(A); w,_=np.linalg.eig(A)
    if abs(lam) < np.max(np.abs(w))-1e-6: mis+=1
print('nondom',mis)
for n in [2,4,6,8,10]:
    d=[];
    for _ in range(200):
        A=np.random.normal(size=(n,n)); t0=time.perf_counter(); F(A); d.append(time.perf_counter()-t0)
    r=[];
    for _ in range(200):
        A=np.random.normal(size=(n,n)); t0=time.perf_counter(); w,v=np.linalg.eig(A); i=np.argmax(np.abs(w)); r.append(time.perf_counter()-t0)
    print(f"n={n} mine={statistics.median(d)*1e6:.1f} ref={statistics.median(r)*1e6:.1f} x={statistics.median(r)/statistics.median(d):.2f}")
